import { defineConfig } from "vitest/config";

export default defineConfig({
  test: {
    globals: true,
    environment: "node",
    include: ["tests/**/*.test.ts"],
    coverage: {
      provider: "v8",
      include: ["src/**/*.ts"],
      // server.ts is the process entrypoint (starts Fastify, binds ports);
      // it is exercised by running the app, not by unit tests.
      // src/generated/prisma/** is vendor code generated by `prisma generate`
      // (each file is headed "code generated by Prisma. Do not edit directly").
      // src/runtime/runnerTypes.ts contains only `interface`/`import type`
      // declarations, which TypeScript erases entirely at compile time, so the
      // emitted module has zero executable statements to cover.
      exclude: ["src/server.ts", "src/generated/prisma/**", "src/runtime/runnerTypes.ts"],
      reporter: ["text", "json-summary", "html"],
      reportsDirectory: "coverage",
    },
  },
});
